Section Stage.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMB.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis EXT : HAJ.asan_ext_ok L ar SCFG HI PMB.EXT.
Let LYa := PMB.ly_as0 L C LY.

Theorem empty : PMB.opnew_spec L ar HI -> forall (fx : FPState) R M model K LBX FF LK Aw cr v sp r p1 p2 p3 m n t,
    ri_inv HI LBX FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA PeCLayoutB.CADDR_B L ar R M sp r 0 ->
    getr R (reg 10) = Z_to_bv 64 v -> PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> PMSPA.accA M v 24 ->
    L5.u64_at RSEGS M v 0 -> L5.u64_at RSEGS M (v + 8) 0 -> L5.u64_at RSEGS M (v + 16) 0 ->
    getr R (reg 11) = Z_to_bv 64 p1 -> getr R (reg 12) = Z_to_bv 64 p2 -> getr R (reg 13) = Z_to_bv 64 p3 -> p1 mod 4 = 0 -> p2 mod 4 = 0 ->
    byte_at M (S p1) 0 -> byte_at M (S p2) 0 -> byte_at M (S p3) 0 ->
    PMBEK.argp (ar_sptop ar) FF sp v p1 4 -> PMBEK.argp (ar_sptop ar) FF sp v p2 4 -> PMBEK.argp (ar_sptop ar) FF sp v p3 1 ->
    L5.u32_at RSEGS M p1 m -> L5.u32_at RSEGS M p2 n -> L5.u8_at RSEGS M p3 t -> 0 <= m < 2 ^ 31 -> 0 <= n < 2 ^ 31 -> 0 <= t < 256 -> acredit_ok L cr 32 ->
    (forall (fx' : FPState) R' M' model' LK' Aw' b', regs_preserved R R' -> getr R' (reg 10) = Z_to_bv 64 (b' + 32) -> PM.vec_at RSEGS PMSPA.accA PMSPA.annA M' v b' 0 [PM.PS m n t 0] ->
        PMSPA.accA M' v 24 -> L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [(v, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vec_own b' 0 ++ LBX) FF LK' (adebit L cr 32) Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R 0xb6c9c M model) K.
Proof.
